package com.techie345.moneys.financial.goal;
import java.time.LocalDate; import java.util.UUID; import com.techie345.moneys.financial.FinancialEntity; import jakarta.persistence.*;
@Entity @Table(name="savings_goal") public class GoalEntity extends FinancialEntity { @Column(nullable=false) String name; @Column(name="target_cents",nullable=false) long targetCents; @Column(name="current_cents",nullable=false) long currentCents; LocalDate deadline; protected GoalEntity(){} public GoalEntity(UUID o,String n,long t,long c,LocalDate d){ownerId=o;name=n;targetCents=t;currentCents=c;deadline=d;} public String getName(){return name;} public long getTargetCents(){return targetCents;} public long getCurrentCents(){return currentCents;} public LocalDate getDeadline(){return deadline;} public void update(String n,long t,long c,LocalDate d){name=n;targetCents=t;currentCents=c;deadline=d;} }
